import{_ as t,o as a,c as o,a2 as i}from"./chunks/framework.DDY-poMm.js";const u=JSON.parse('{"title":"Site Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"guide/site-config.md","filePath":"guide/site-config.md","lastUpdated":1790683574000}'),r={name:"guide/site-config.md"};function n(s,e,d,c,h,l){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="site-configuration" tabindex="-1">Site Configuration <a class="header-anchor" href="#site-configuration" aria-label="Permalink to &quot;Site Configuration&quot;">​</a></h1><p>Most of what users see — menus, icons, featured coins, VIP tiers and so on — is <strong>not hard-coded</strong>. Operators adjust it under &quot;Basic Configuration&quot; in the admin console. Once saved, it takes effect the next time the user side is opened, with no engineering work and no new release.</p><p>This page first goes through each tab under &quot;Basic Configuration&quot;, then explains the eight integration cards on the &quot;Third-Party Configuration&quot; page.</p><h2 id="side-menu" tabindex="-1">Side menu <a class="header-anchor" href="#side-menu" aria-label="Permalink to &quot;Side menu&quot;">​</a></h2><p>The list of entries on the user side&#39;s &quot;Me&quot; page. For each item you can configure the name, icon, link target, order and on/off switch.</p><p>Turning an item off removes that entry from the user side.</p><div class="danger custom-block"><p class="custom-block-title">The key here decides which page the app opens</p><p>Each item has a <strong>key</strong>. The app <strong>uses the key to decide which native page to open</strong> — with the correct key, tapping it opens a smooth native page; <strong>if the key is wrong or the item is not configured, the entry simply does not exist in the app</strong>.</p><p>Common keys with native pages (the app will not recognize a mistyped key):</p><table tabindex="0"><thead><tr><th>key</th><th>Feature</th></tr></thead><tbody><tr><td><code>service</code></td><td><strong>Live chat</strong> (see <a href="/CoinExchange/guide/customer-service">Customer Service</a>)</td></tr><tr><td><code>helper</code></td><td>Help center</td></tr><tr><td><code>language</code></td><td>Languages</td></tr><tr><td><code>primary</code> / <code>advanced</code></td><td>Basic verification / identity verification</td></tr><tr><td><code>certified</code></td><td>Email verification</td></tr><tr><td><code>bank</code></td><td>Bind bank card</td></tr><tr><td><code>tardPwd</code> / <code>loginPwd</code></td><td>Fund password / login password</td></tr><tr><td><code>termsService</code></td><td>Terms of service</td></tr><tr><td><code>paper</code></td><td>White paper</td></tr></tbody></table><p><strong>If a feature entry is missing in the app, first check here whether its key is configured and enabled</strong> — that is much faster than suspecting the app.</p></div><div class="tip custom-block"><p class="custom-block-title">Home shortcuts work the same way</p><p>The key rules for the home shortcut grid are the same as here (e.g. <code>financial</code> wealth management, <code>pledge</code> staking, <code>subscription</code> token subscription, <code>download_center</code> download center, <code>promotion_center</code> referral center).</p></div><h2 id="bottom-bar" tabindex="-1">Bottom bar <a class="header-anchor" href="#bottom-bar" aria-label="Permalink to &quot;Bottom bar&quot;">​</a></h2><p>The user side&#39;s bottom navigation bar (Home / Markets / Trade / Assets, etc.). You can configure the name, selected and unselected icons, link target, order and on/off switch.</p><div class="warning custom-block"><p class="custom-block-title">Note</p><p>The bottom bar is the backbone of the user side. <strong>Keep at least Home and Assets</strong> — turning everything off leaves users unable to navigate.</p></div><h2 id="home-shortcuts" tabindex="-1">Home shortcuts <a class="header-anchor" href="#home-shortcuts" aria-label="Permalink to &quot;Home shortcuts&quot;">​</a></h2><p>The grid of quick-access entries at the top of the home page. Configured the same way as the side menu.</p><h2 id="featured-coins" tabindex="-1">Featured coins <a class="header-anchor" href="#featured-coins" aria-label="Permalink to &quot;Featured coins&quot;">​</a></h2><p>Which coins the home market list shows by default, and in what order.</p><h2 id="asset-tabs" tabindex="-1">Asset tabs <a class="header-anchor" href="#asset-tabs" aria-label="Permalink to &quot;Asset tabs&quot;">​</a></h2><p>The section tabs on the user&#39;s asset page (e.g. spot assets, contract assets, wealth assets). Turn one off and the asset page no longer shows that section.</p><h2 id="product-configuration" tabindex="-1">Product configuration <a class="header-anchor" href="#product-configuration" aria-label="Permalink to &quot;Product configuration&quot;">​</a></h2><p>Master switches for each trading product. Turning one off hides the corresponding entry on the user side.</p><h2 id="platform-logo" tabindex="-1">Platform logo <a class="header-anchor" href="#platform-logo" aria-label="Permalink to &quot;Platform logo&quot;">​</a></h2><p>The platform logo and icons in each size (57×57 / 72×72 / 120×120 / 144×144).</p><h2 id="vip-tiers-vip-description" tabindex="-1">VIP tiers / VIP description <a class="header-anchor" href="#vip-tiers-vip-description" aria-label="Permalink to &quot;VIP tiers / VIP description&quot;">​</a></h2><ul><li><strong>VIP tiers</strong>: the threshold for each tier</li><li><strong>VIP description</strong>: the benefit text shown to users</li></ul><h2 id="download-links" tabindex="-1">Download links <a class="header-anchor" href="#download-links" aria-label="Permalink to &quot;Download links&quot;">​</a></h2><p>The list of download entries shown in the user side&#39;s &quot;Download Center&quot;; each item has a name, download URL, order and on/off switch.</p><div class="tip custom-block"><p class="custom-block-title">How this differs from app auto-update</p><p>The download center is <strong>for new users to install the app</strong>; existing users are updated through auto-update, configured under &quot;App Version Update&quot;. The two are independent, but we recommend pointing them at the same version.</p></div><h2 id="app-version-update" tabindex="-1">App version update <a class="header-anchor" href="#app-version-update" aria-label="Permalink to &quot;App version update&quot;">​</a></h2><p>Controls whether users with the app installed receive a new-version prompt. <strong>This is a super-admin-only setting.</strong> See <a href="/CoinExchange/guide/app-release">App Releases</a>.</p><h2 id="sign-up-and-login" tabindex="-1">Sign-up and login <a class="header-anchor" href="#sign-up-and-login" aria-label="Permalink to &quot;Sign-up and login&quot;">​</a></h2><p>Controls which methods users can register and log in with (email / phone / username / wallet address), and the initial credit score of new users.</p><h2 id="captcha-time-zone" tabindex="-1">Captcha / time zone <a class="header-anchor" href="#captcha-time-zone" aria-label="Permalink to &quot;Captcha / time zone&quot;">​</a></h2><ul><li><strong>Captcha</strong>: settings for the image captcha</li><li><strong>Time zone</strong>: the platform&#39;s reference time zone, affecting time display in the admin console and on the user side</li></ul><h2 id="white-paper" tabindex="-1">White paper <a class="header-anchor" href="#white-paper" aria-label="Permalink to &quot;White paper&quot;">​</a></h2><p>The URL of the platform white paper.</p><div class="warning custom-block"><p class="custom-block-title">Tip</p><p>Use a <strong>web page or PDF</strong>. If it points to a <code>.doc</code> file, users may not be able to preview it directly.</p></div><h2 id="notification-sounds" tabindex="-1">Notification sounds <a class="header-anchor" href="#notification-sounds" aria-label="Permalink to &quot;Notification sounds&quot;">​</a></h2><p>Sounds played in the admin console when deposit / withdrawal events arrive.</p><h2 id="admin-ip-control" tabindex="-1">Admin IP control <a class="header-anchor" href="#admin-ip-control" aria-label="Permalink to &quot;Admin IP control&quot;">​</a></h2><p>Restricts which IPs can access the admin console. <strong>Super-admin-only setting.</strong></p><div class="danger custom-block"><p class="custom-block-title">High-risk operation</p><p>A misconfiguration can lock you out of the console as well. Before changing it, make sure the outbound IP you are currently using is on the allowlist.</p></div><h2 id="data-masking" tabindex="-1">Data masking <a class="header-anchor" href="#data-masking" aria-label="Permalink to &quot;Data masking&quot;">​</a></h2><p>Masking switches for each business module, with a master switch and per-product sub-switches.</p><hr><h2 id="third-party" tabindex="-1">Third-party configuration <a class="header-anchor" href="#third-party" aria-label="Permalink to &quot;Third-party configuration {#third-party}&quot;">​</a></h2><p>This is a separate page from &quot;Basic Configuration&quot;. It holds <strong>the platform&#39;s integration details with external services</strong> — rarely changed, but with a large impact if wrong. We recommend that a super administrator or one designated operator owns it.</p><table tabindex="0"><thead><tr><th>Card</th><th>What it is</th><th>Who can change it</th></tr></thead><tbody><tr><td>SMS</td><td>Account, password and endpoint of the SMS provider, used for phone verification codes</td><td>Operators with configuration permission</td></tr><tr><td>Email</td><td>Sender account, password, server address and port, used for email verification codes and notifications</td><td>Operators with configuration permission</td></tr><tr><td>OSS</td><td>Domain, account and bucket of object storage (images, attachments); user avatars, KYC documents and chat images are stored here</td><td>Operators with configuration permission</td></tr><tr><td>TG bot</td><td><strong>Deposit / withdrawal alert bot</strong> that pushes deposit and withdrawal events to the operators&#39; Telegram group. The group ID is written automatically when the bot first joins; no need to fill it in</td><td>Operators with configuration permission</td></tr><tr><td>UDUN</td><td>Gateway URL, merchant ID, merchant key and callback URL of the UDUN deposit/withdrawal channel</td><td><strong>Super administrator only</strong></td></tr><tr><td>Payment gateway</td><td><strong>Choose one</strong>: whether the deposit channel currently active for users is &quot;UDUN&quot; or &quot;TokenPay&quot;</td><td><strong>Super administrator only</strong></td></tr><tr><td>TokenPay</td><td>Service URL, ApiToken, callback URL and enable switch of the TokenPay channel. See <a href="/CoinExchange/guide/finance">Deposits &amp; Withdrawals</a></td><td><strong>Super administrator only</strong></td></tr><tr><td>Live chat</td><td>Support bot token, support group ID, callback URL and secret. See <a href="/CoinExchange/guide/customer-service">Customer Service</a></td><td>Operators with configuration permission</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">The two Telegram bots cannot be shared</p><p>The &quot;TG bot&quot; (alerts) and &quot;Live chat&quot; (support) <strong>must be two different bots</strong>. Sharing one token makes them steal each other&#39;s messages, and neither receives everything.</p></div><div class="tip custom-block"><p class="custom-block-title">Secrets are not displayed</p><p>After saving, password and key fields no longer show the original value (only that it is set). Keep a backup elsewhere before changing them; otherwise, if you enter it wrong, you will have to request it from the provider again.</p></div><div class="danger custom-block"><p class="custom-block-title">Before switching the payment gateway</p><p>First make sure the target channel&#39;s card is <strong>filled in and enabled</strong>, then switch &quot;Payment gateway&quot;. Switching to a channel that is not configured makes deposits fail immediately for users.</p></div>',49)])])}const g=t(r,[["render",n]]);export{u as __pageData,g as default};
